    { t: "yn", q: "Können Kröten über die Zäune klettern?", a: false, h: "Die Kröten können nicht darüber klettern" },
    { t: "mc", q: "Was machen die Helfer am Morgen?", o: ["Sie bauen den Zaun ab", "Sie füttern die Kröten", "Sie tragen die Eimer über die Straße"], a: 2, h: "tragen Helfer die Eimer vorsichtig über die Straße" },
    { t: "yn", q: "Gibt es an manchen Straßen Tunnel für Kröten?", a: true, h: "An manchen Straßen gibt es sogar kleine Tunnel für Kröten." }
